/**
 * T-step-color (Task 9): End-to-end verification that per-body STEP colors
 * are rendered in both the single-part viewport and the assembly viewport
 * (after Explode Into Assembly), and that colors survive a page reload.
 *
 * Fixture: two-colored-boxes.step — two disjoint 10×10×10 boxes with XCAF
 * surface colors #ff0000 (red, box 0 at x=0) and #00ff00 (green, box 1 at
 * x=20). Generated by tools/generate-colored-step-fixture.mjs.
 *
 * Color access in page.evaluate:
 *   Part-mode:    useAppStore.getState().viewport?.getSceneManager()?.getCurrentMesh()?.material.color
 *   Assembly:     window.__zilventorComponentMaterialHexByPath([componentId])
 *
 * The assembly path requires showComponentColors=true (off by default).
 */
import { test, expect } from '@playwright/test';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { waitForKernelReady } from '../helpers/buildBox';
import { waitForAutosave } from '../helpers/waitForAutosave';

const TWO_COLORED_BOXES = resolve(
  __dirname,
  '../../../packages/kernel/src/occt/__tests__/fixtures/step/two-colored-boxes.step',
);

const EXPECTED_COLORS = new Set(['#ff0000', '#00ff00']);

test(
  'T-step-color: colored STEP renders per-body color in part + assembly views, survives reload',
  async ({ page }) => {
    const pageErrors: string[] = [];
    page.on('pageerror', (e) => {
      pageErrors.push(e.message);
      console.log('PAGEERROR:', e.message);
    });
    page.on('console', (m) => {
      if (m.type() === 'error') console.log('BROWSER ERROR:', m.text());
    });

    // ── 1. Boot ──────────────────────────────────────────────────────────────
    await page.goto('/');
    await waitForKernelReady(page);

    // Confirm clean starting state (no active document).
    const initialDoc = await page.evaluate(
      () => (window as any).__zilventorStore?.getState().activeDocument ?? null,
    );
    expect(initialDoc).toBeNull();

    // ── 2. Override showOpenFilePicker → two-colored-boxes.step ─────────────
    const stepBytes = readFileSync(TWO_COLORED_BOXES);
    await page.evaluate(
      async ([bytes]: [number[]]) => {
        const fakeFile = {
          name: 'two-colored-boxes.step',
          arrayBuffer: async () => new Uint8Array(bytes).buffer,
        };
        const fakeHandle = { getFile: async () => fakeFile };
        (window as any).showOpenFilePicker = async () => [fakeHandle];
      },
      [Array.from(stepBytes)] as [number[]],
    );

    // ── 3. File → Open → wait for part ──────────────────────────────────────
    await page.getByRole('tab', { name: 'File' }).click();
    await page.getByRole('button', { name: /open/i }).click();

    await page.waitForFunction(
      () => (window as any).__zilventorStore?.getState().activeDocument?.kind === 'part',
      undefined,
      { timeout: 60_000 },
    );

    // Verify the part has an imported feature with a color.
    const partState = await page.evaluate(async () => {
      const { useAppStore } = await import('/src/store/useAppStore.ts');
      const s = useAppStore.getState();
      const part = s.activePart;
      const imp = part?.featureTree?.find((f: any) => f.kind === 'imported') as any;
      return {
        partName: part?.name ?? null,
        partColorKind: part?.color?.kind ?? null,
        partColorHex: part?.color?.kind === 'hex' ? part.color.hex : null,
        importedFeatureColor: imp?.color ?? null,
      };
    });

    expect(partState.partName).toBe('two-colored-boxes');
    // The compound has 2 solids — part-mode opens the WHOLE compound as one part.
    // The part color comes from the FIRST solid in the compound enumeration.
    // It must be one of the two expected STEP colors (either red or green).
    expect(partState.partColorKind).toBe('hex');
    expect(EXPECTED_COLORS.has(partState.partColorHex!)).toBe(true);

    // ── 4. Assert part-mode mesh material color = STEP color ─────────────────
    // Wait for the mesh to be set (the activePart useEffect fires asynchronously).
    // Poll until getCurrentMesh() returns a non-null mesh AND has a color.
    const partMeshColor = await page.waitForFunction(
      () => {
        const w = window as any;
        // Use the store's viewport field → getSceneManager() → getCurrentMesh()
        const sm = w.__zilventorStore?.getState()?.viewport?.getSceneManager?.();
        const mesh = sm?.getCurrentMesh?.();
        const mat = mesh?.material;
        if (!mat || !('color' in mat)) return null;
        const hex = '#' + mat.color.getHexString();
        // Exclude the default gray (part not yet colored)
        if (hex === '#c8c8c8') return null;
        return hex;
      },
      undefined,
      { timeout: 15_000 },
    );

    const partHex = await partMeshColor.jsonValue() as string;
    expect(EXPECTED_COLORS.has(partHex)).toBe(true);
    console.log('Part-mode mesh color:', partHex);

    // ── 5. Switch to Model tab → click Explode Into Assembly ─────────────────
    await page.getByRole('tab', { name: /^model$/i }).click();

    const explodeBtn = page.getByRole('button', { name: /explode into assembly/i });
    await expect(explodeBtn).toBeVisible({ timeout: 5_000 });
    await expect(explodeBtn).toBeEnabled({ timeout: 5_000 });

    // Enable showComponentColors so the assembly renders per-body colors.
    await page.evaluate(async () => {
      const { useAppStore } = await import('/src/store/useAppStore.ts');
      useAppStore.getState().setShowComponentColors(true);
    });

    await explodeBtn.click();

    // ── 6. Wait for assembly with 2 components ───────────────────────────────
    await page.waitForFunction(
      () => {
        const doc = (window as any).__zilventorStore?.getState().activeDocument;
        return doc?.kind === 'assembly' && doc.document.components.length === 2;
      },
      undefined,
      { timeout: 30_000 },
    );

    // ── 7. Read component colors from the store (ground truth) ───────────────
    const asmState = await page.evaluate(async () => {
      const { useAppStore } = await import('/src/store/useAppStore.ts');
      const s = useAppStore.getState();
      const doc = s.activeDocument;
      if (doc?.kind !== 'assembly') return null;
      const components: Array<{ id: string; partPath: string; color?: { kind: string; hex?: string } }> =
        doc.document.components;
      return {
        componentCount: components.length,
        components: components.map((c) => ({
          id: c.id,
          partPath: c.partPath,
          colorKind: c.color?.kind ?? null,
          colorHex: c.color?.kind === 'hex' ? c.color.hex : null,
        })),
      };
    });

    expect(asmState).not.toBeNull();
    expect(asmState!.componentCount).toBe(2);

    // Both components must have hex colors matching the STEP colors.
    const componentColors = asmState!.components.map((c) => c.colorHex);
    expect(componentColors.every((h) => h !== null)).toBe(true);
    expect(new Set(componentColors).size).toBe(2);
    for (const hex of componentColors) {
      expect(EXPECTED_COLORS.has(hex!)).toBe(true);
    }
    console.log('Assembly component colors:', componentColors);

    // ── 8. Assert assembly viewport renders the colors ────────────────────────
    // Wait for the component meshes to be set with colors.
    // Use __zilventorComponentMaterialHexByPath (mirrors subasm-color-override test).
    const firstId = asmState!.components[0]!.id;
    const secondId = asmState!.components[1]!.id;

    await expect.poll(
      async () => page.evaluate(
        ([id]: [string]) => {
          const w = window as any;
          return w.__zilventorComponentMaterialHexByPath?.([id]) ?? null;
        },
        [firstId] as [string],
      ),
      { timeout: 10_000 },
    ).not.toBeNull();

    const firstMeshColor = await page.evaluate(
      ([id]: [string]) => {
        const w = window as any;
        return w.__zilventorComponentMaterialHexByPath?.([id]) ?? null;
      },
      [firstId] as [string],
    );
    const secondMeshColor = await page.evaluate(
      ([id]: [string]) => {
        const w = window as any;
        return w.__zilventorComponentMaterialHexByPath?.([id]) ?? null;
      },
      [secondId] as [string],
    );

    // Both assembly mesh materials must match the STEP colors.
    expect(firstMeshColor).not.toBeNull();
    expect(secondMeshColor).not.toBeNull();
    expect(EXPECTED_COLORS.has(firstMeshColor!)).toBe(true);
    expect(EXPECTED_COLORS.has(secondMeshColor!)).toBe(true);
    // They must be different (two distinct colored boxes).
    expect(firstMeshColor).not.toBe(secondMeshColor);
    console.log('Assembly mesh colors:', firstMeshColor, secondMeshColor);

    // ── 9. Wait for autosave + reload ────────────────────────────────────────
    await waitForAutosave(page);

    // Also persist showComponentColors to verify it's still enabled after reload.
    // (It's persisted in-memory only for this session, not OPFS. Re-enable after.)
    await page.reload();
    await waitForKernelReady(page);

    // ── 10. After reload: assert assembly restores with correct component colors
    await page.waitForFunction(
      () => {
        const w = window as any;
        const doc = w.__zilventorStore?.getState().activeDocument;
        return doc?.kind === 'assembly' && doc.document.components.length >= 2;
      },
      undefined,
      { timeout: 15_000 },
    );

    const afterReload = await page.evaluate(async () => {
      const { useAppStore } = await import('/src/store/useAppStore.ts');
      // Re-enable showComponentColors (resets on reload).
      useAppStore.getState().setShowComponentColors(true);
      const s = useAppStore.getState();
      const doc = s.activeDocument;
      if (doc?.kind !== 'assembly') return null;
      return {
        componentCount: doc.document.components.length,
        components: doc.document.components.map((c: any) => ({
          id: c.id,
          colorKind: c.color?.kind ?? null,
          colorHex: c.color?.kind === 'hex' ? c.color.hex : null,
        })),
      };
    });

    expect(afterReload).not.toBeNull();
    expect(afterReload!.componentCount).toBe(2);

    // Component colors persist across reload via OPFS.
    const reloadedColors = afterReload!.components.map((c: any) => c.colorHex);
    expect(reloadedColors.every((h: string | null) => h !== null)).toBe(true);
    expect(new Set(reloadedColors).size).toBe(2);
    for (const hex of reloadedColors) {
      expect(EXPECTED_COLORS.has(hex!)).toBe(true);
    }
    console.log('Reload: component colors:', reloadedColors);

    // Also verify the assembly renders colors in the viewport after reload.
    const afterReloadIds = afterReload!.components.map((c: any) => c.id as string);

    await expect.poll(
      async () => page.evaluate(
        ([id]: [string]) => {
          const w = window as any;
          return w.__zilventorComponentMaterialHexByPath?.([id]) ?? null;
        },
        [afterReloadIds[0]!] as [string],
      ),
      { timeout: 15_000 },
    ).not.toBeNull();

    const reloadFirstMesh = await page.evaluate(
      ([id]: [string]) => {
        const w = window as any;
        return w.__zilventorComponentMaterialHexByPath?.([id]) ?? null;
      },
      [afterReloadIds[0]!] as [string],
    );
    const reloadSecondMesh = await page.evaluate(
      ([id]: [string]) => {
        const w = window as any;
        return w.__zilventorComponentMaterialHexByPath?.([id]) ?? null;
      },
      [afterReloadIds[1]!] as [string],
    );

    expect(EXPECTED_COLORS.has(reloadFirstMesh!)).toBe(true);
    expect(EXPECTED_COLORS.has(reloadSecondMesh!)).toBe(true);
    expect(reloadFirstMesh).not.toBe(reloadSecondMesh);
    console.log('Reload: assembly mesh colors:', reloadFirstMesh, reloadSecondMesh);

    // ── 11. No uncaught page errors ───────────────────────────────────────────
    expect(pageErrors).toHaveLength(0);
  },
);
